import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from collections import deque
def size_of(g,r,c):
    h=len(g); w=len(g[0]); v=g[r][c]; q=deque([(r,c)]); vis={(r,c)}; n=0
    while q:
        rr,cc=q.popleft(); n+=1
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=rr+dr,cc+dc
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==v and (nr,nc) not in vis:
                vis.add((nr,nc)); q.append((nr,nc))
    return n
def f(g):
    h=len(g); w=len(g[0])
    cnt={}
    for row in g:
        for v in row: cnt[v]=cnt.get(v,0)+1
    bg=max(cnt,key=lambda v:(cnt[v],v))
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if size_of(g,r,c)==1:
                nb=[]
                for dr,dc in dirs:
                    nr,nc=r+dr,c+dc
                    if 0<=nr<h and 0<=nc<w: nb.append(g[nr][nc])
                mx=max(set(nb),key=lambda x:(nb.count(x), -1 if x==bg else 0))
                out[r][c]=mx
    return out
ti=G['Test input']; tg=f(ti)
